				{/each}
			</ul>
		{:else}
			<p class="mt-3 text-ink/60">
				no conversations yet. open any product and message the builder to start one.
			</p>
		{/if}
	</div>
</div>

The search box obeys the repo's form rule: a bare Enter is swallowed by the `onkeydown` guard (a single-input form implicitly submits on Enter in every browser, so the guard is required, not optional), and ctrl/cmd+Enter submits through `use:ctrl_enter`. The page is `noindex` because it is private.

inbox_thread.s:
Build /inbox/[id]: one conversation, oldest message at the top, a composer at the bottom, and a five-second poll so a reply arriving while the page is open appears without a reload. This is the entire "realtime" story — there is no WebSocket and no Durable Object in dc2.

FILE 1 — create src/routes/inbox/[id]/+page.server.ts with exactly this content:

import type { PageServerLoad } from './$types';
import { error, redirect } from '@sveltejs/kit';
import { env } from '$env/dynamic/private';
import { get_conv, get_thread, mark_read } from '$lib/server/chat';
import { in_conv, norm, peer_of } from '$lib/chat';

export const load: PageServerLoad = async ({ params, locals }) => {
	if (!locals.user) throw redirect(302, '/google?next=/inbox');
	const me = norm(locals.user.e);
	const c = await get_conv(env, params.id);
	if (!c || !in_conv(c, me)) throw error(404, 'not found');
	const msgs = await get_thread(env, c.cv);
	await mark_read(env, c, me);
	return { me, id: params.id, who: peer_of(c, me), pg: c.pg, pn: c.pn, msgs };
};

A conversation somebody is not part of returns 404, not 403: a stranger learns nothing about whether that id exists.

FILE 2 — create src/routes/inbox/[id]/+page.svelte with exactly this content:

<script lang="ts">
	import type { PageData } from './$types';
	import { ctrl_enter } from '$lib/ctrl_enter';
	import Icon from '$lib/icon.svelte';
	import type { Msg } from '$lib/chat';

	let { data }: { data: PageData } = $props();

	let msgs = $state<Msg[]>([]);
	let text = $state('');
	let busy = $state(false);
	let err = $state('');
	let form: HTMLFormElement;

	$effect(() => {
		msgs = [...(data.msgs as Msg[])];
	});

	$effect(() => {
		const tick = setInterval(async () => {
			const after = msgs.length ? msgs[msgs.length - 1].md : 0;
			const r = await fetch(`/api/msg?id=${data.id}&after=${after}`);
			if (!r.ok) return;
			const { m } = (await r.json()) as { m: Msg[] };
			if (m.length) msgs = [...msgs, ...m];
		}, 5000);
		return () => clearInterval(tick);
	});

	async function send() {
		if (busy || !text.trim()) return;
		busy = true;
		err = '';
		try {
			const r = await fetch('/api/msg', {
				method: 'POST',
				headers: { 'content-type': 'application/json' },
				body: JSON.stringify({ id: data.id, x: text })
			});
			if (!r.ok) throw new Error((await r.text()) || 'that did not send');
			const { m } = (await r.json()) as { m: Msg };
			msgs = [...msgs, m];
			text = '';
		} catch (e) {
			err = e instanceof Error ? e.message : 'that did not send';
		} finally {
			busy = false;
		}
	}

	const when = (md: number) =>
		new Date(md).toLocaleString('en-GB', {
			day: 'numeric',
			month: 'short',
			hour: '2-digit',
			minute: '2-digit'
		});
</script>

<svelte:head>
	<title>{data.who} — devcircles</title>
	<meta name="robots" content="noindex" />
</svelte:head>

<div class="mx-auto max-w-3xl px-6 py-16">
	<a href="/inbox" class="inline-flex items-center gap-2 text-sm text-ink/60 hover:text-cobalt">
		<Icon n="back" c="h-4 w-4" /> inbox
	</a>

	<h1 class="mt-4 font-display text-2xl font-semibold tracking-tight text-ink">{data.who}</h1>
	{#if data.pn}
		<p class="mt-1 text-sm text-ink/60">
			about <a href="/{data.pg}" class="text-cobalt hover:underline">{data.pn.toLowerCase()}</a>
		</p>
	{/if}

	<ul class="mt-10 flex flex-col gap-4">
		{#each msgs as m (m.md + m.mf)}
			<li class="flex {m.mf === data.me ? 'justify-end' : 'justify-start'}">
				<div class="max-w-[80%] rounded-lg px-4 py-3 {m.mf === data.me ? 'bg-cobalt text-white' : 'border border-ink/10 text-ink'}">
					<p class="text-sm whitespace-pre-wrap">{m.mx}</p>
					<p class="mt-1 text-[10px] {m.mf === data.me ? 'text-white/60' : 'text-ink/40'}">{when(m.md)}</p>
				</div>
			</li>
		{/each}
	</ul>

	{#if !msgs.length}
		<p class="mt-6 text-ink/60">no messages yet. say the first thing.</p>
	{/if}

	<form
		bind:this={form}
		use:ctrl_enter={() => form.requestSubmit()}
		onsubmit={(ev) => {
			ev.preventDefault();
			send();
		}}
		class="mt-10 flex flex-col gap-3"
	>
		<textarea
			bind:value={text}
			rows="3"
			placeholder="write a message"
			class="rounded-md border border-ink/20 px-3 py-2 text-sm"
		></textarea>
		{#if err}<p class="text-xs text-coral">{err}</p>{/if}
		<div class="flex items-center gap-4">
			<button
				type="submit"
				disabled={busy}
				class="inline-flex items-center gap-2 rounded-full bg-cobalt px-6 py-3 text-sm font-medium text-white hover:bg-cobalt/90 disabled:opacity-50"
			>
				<Icon n="send" c="h-4 w-4" />
				{busy ? 'sending…' : 'send'}
			</button>
			<span class="text-xs text-ink/50">ctrl+enter sends</span>
		</div>
	</form>
</div>

Details that must survive: the poll asks only for messages strictly newer than the last one already held, so it re-fetches nothing; the interval is cleared by the effect's teardown, so leaving the page stops it; a message the user just sent is appended from the POST response rather than waited for, so sending feels instant; and the textarea keeps a bare Enter as a newline, with ctrl+enter sending, exactly as the repo requires.

