detail_load.s:
Feed the redesigned page: related products, and a fix for a real bug that hides the whole owner experience today.

THE BUG. src/routes/[slug]/+page.server.ts currently reads:

export const load: PageServerLoad = async ({ params, locals }) => {
	const pt = await retrieve_one(env, await uuid_from(params.slug));
	if (!pt || !pt.payload) throw error(404, 'not found');
	const p = pt.payload as Record<string, unknown>;
	const owner = !!locals.user && locals.user.e === p.e;
	delete p.e;
	if (!owner) return { p, asks: [] };
	const pts = await scroll(env, f(eq('s', 'adca'), eq('t', 'x'), eq('pg', params.slug)), 200);
	const asks = pts
		.map((x) => x.payload as Record<string, string>)
		.sort((a, b) => Number(b.j ?? 0) - Number(a.j ?? 0));
	return { p, asks };
};

`delete p.e` runs for everyone, including the owner, and the page then decides ownership on the client with `const is_owner = $derived(!!data.u && data.u.e === p.e)`. Since `p.e` no longer exists in the payload the browser receives, that comparison is always false. So the owner never sees the "edit your page" link, never sees the "still accurate" freshness prompt, and never sees the list of people who asked about their product — even though the server loaded it. Stripping the private email is correct and must stay; sending the verdict instead of the evidence is the fix.

Replace the WHOLE file src/routes/[slug]/+page.server.ts with exactly this content:

import type { PageServerLoad } from './$types';
import { error } from '@sveltejs/kit';
import { env } from '$env/dynamic/private';
import { retrieve_one, uuid_from, scroll, eq, f } from '$lib/server/qdrant';
import { related } from '$lib/detail';
import type { P } from '$lib/investor';

export const load: PageServerLoad = async ({ params, locals }) => {
	const pt = await retrieve_one(env, await uuid_from(params.slug));
	if (!pt || !pt.payload) throw error(404, 'not found');
	const p = pt.payload as Record<string, unknown>;
	const own = !!locals.user && locals.user.e === p.e;
	const can_msg = !!p.e && !own;
	delete p.e;

	const all = (await scroll(env, f(eq('s', 'adca'), eq('t', 'p')), 500)).map((x) => {
		const o = { ...(x.payload as Record<string, string>) };
		delete o.e;
		return o;
	});
	const rel = related(all, p as P, 3).map((o) => ({ g: o.g, n: o.n, o: o.o, c: o.c }));

	if (!own) return { p, own, can_msg, rel, asks: [] };
	const pts = await scroll(env, f(eq('s', 'adca'), eq('t', 'x'), eq('pg', params.slug)), 200);
	const asks = pts
		.map((x) => x.payload as Record<string, string>)
		.sort((a, b) => Number(b.j ?? 0) - Number(a.j ?? 0));
	return { p, own, can_msg, rel, asks };
};

Three things this now returns that it did not before: `own`, the server's own verdict on ownership; `can_msg`, true only when the product has a builder email on file and the viewer is not that builder; and `rel`, three related products reduced to the four fields the sidebar shows. Every product in `all` has its private `e` deleted from a COPY before anything leaves the server — note the `{ ...x.payload }` spread, which matters because deleting from the payload object itself would mutate whatever the Qdrant client handed back.

Then, in src/routes/[slug]/+page.svelte, find:

	const is_owner = $derived(!!data.u && data.u.e === p.e);

and replace it with:

	const is_owner = $derived(!!data.own);

That one line makes the owner's edit link, freshness prompt and interest inbox appear for the first time. The rest of that file is rewritten in the next step.

